 "content": "def transform(grid):
    """Encode counts of isolated T tetromino orientations in two 3x3 panels."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 1: 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(cells) != 4:
                continue
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            r0, r1 = min(rs), max(rs)
            c0, c1 = min(cs), max(cs)
            if r1-r0 != 1 or c1-c0 != 2:
                continue
            row_counts = [sum((rr, cc) in set(cells) for cc in range(c0, c1+1)) for rr in (r0, r1)]
            if row_counts == [1, 3]:
                counts[3] += 1
            elif row_counts == [3, 1]:
                counts[1] += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for color, offset in ((3, 0), (1, 3)):
        for rr, cc in slots[:min(counts[color], 4)]:
            out[rr][cc + offset] = color
    return out


